insert into public.organizations (id, name, tagline, description, industry, size_band, location, website, district_id, logo_color, follower_count, verified, created_at) values
  ('org-northwind', 'Northwind Systems', 'Payments infrastructure for African commerce.', 'Northwind builds the settlement rails behind thousands of merchants across West Africa. Small teams, long-lived services, a strong bias toward writing things down.', 'Fintech', '120-400', 'Lagos, Nigeria', 'https://example.com/northwind', 'technology-hub', '#6fe0ff', 4820, true, '2024-03-11T09:00:00.000Z'),
  ('org-meridian', 'Meridian Capital Partners', 'Investment research and advisory.', 'A mid-sized advisory firm covering infrastructure and energy across emerging markets. Analysts rotate across sectors in their first two years.', 'Financial Services', '400-1200', 'Lagos, Nigeria', 'https://example.com/meridian', 'finance-district', '#9fb2d8', 2140, true, '2023-08-02T09:00:00.000Z'),
  ('org-lumen', 'Lumen Studio', 'Brand, motion and product design.', 'An independent studio working with consumer brands and early-stage products. Known for a strong in-house motion practice.', 'Design & Media', '20-60', 'Remote (WAT ±3)', 'https://example.com/lumen', 'creative-district', '#d98cff', 7310, false, '2024-11-20T09:00:00.000Z'),
  ('org-vitalis', 'Vitalis Health Group', 'Clinics, diagnostics and care coordination.', 'Operates eleven outpatient clinics and a diagnostics network, with a growing digital care team supporting remote follow-up.', 'Healthcare', '1200-3000', 'Abuja, Nigeria', 'https://example.com/vitalis', 'healthcare-district', '#76e8a8', 3380, true, '2022-05-14T09:00:00.000Z'),
  ('org-azure-bay', 'Azure Bay Hotels', 'Boutique hospitality across the coast.', 'Nine properties with a reputation built on service training. Promotes from within and runs its own hospitality academy.', 'Hospitality', '600-1500', 'Lagos, Nigeria', 'https://example.com/azurebay', 'hospitality-district', '#ff9f7a', 1890, false, '2023-02-27T09:00:00.000Z'),
  ('org-keystone', 'Keystone Talent', 'Specialist recruitment for operations and HR roles.', 'A recruitment partner placing operations, people and finance talent. Runs structured assessments before any client introduction.', 'Recruitment', '40-120', 'Lagos / Remote', 'https://example.com/keystone', 'recruitment-agency', '#5be3c8', 5640, true, '2024-01-09T09:00:00.000Z'),
  ('org-brightpath', 'Brightpath Learning', 'Professional certification and upskilling.', 'Delivers accredited short courses in data, finance and operations, with assessment-backed certificates employers recognise.', 'Education', '80-250', 'Remote', 'https://example.com/brightpath', 'university-campus', '#ffc46b', 9120, true, '2023-06-30T09:00:00.000Z'),
  ('org-atlas-holdings', 'Atlas Holdings', 'Diversified industrial and consumer group.', 'A holding company with interests in logistics, manufacturing and retail. Central functions sit in the corporate office.', 'Conglomerate', '3000+', 'Lagos, Nigeria', 'https://example.com/atlas', 'corporate-district', '#7f9cff', 6450, true, '2021-10-05T09:00:00.000Z'),
  ('org-signal-labs', 'Signal Labs', 'Applied machine learning for logistics.', 'A twenty-person research and product team building routing and demand forecasting tools used by regional distributors.', 'Technology', '20-60', 'Remote', 'https://example.com/signallabs', 'technology-hub', '#6c8cff', 2760, false, '2025-04-18T09:00:00.000Z'),
  ('org-harbour-co', 'Harbour & Co.', 'Audit, tax and advisory.', 'A professional services firm with a strong graduate programme and a clear path from associate to manager.', 'Accounting', '400-900', 'Lagos, Nigeria', 'https://example.com/harbour', 'finance-district', '#b8c6e4', 3010, true, '2022-09-12T09:00:00.000Z')
insert into public.jobs (id, organization_id, company_name, title, description, salary_min, salary_max, currency, salary_period, location, work_type, employment_type, experience_level, required_skills, preferred_skills, industry, district_id, deadline, status, source, responsibilities, requirements, featured, created_at) values
  ('job-001', 'org-northwind', 'Northwind Systems', 'Backend Engineer', 'Own settlement services that move money between merchants and banks. You will work on correctness-critical code with a team that reviews carefully and ships steadily.', 500000, 800000, 'NGN', 'month', 'Lagos / Remote', 'remote', 'full-time', 'mid', '{Node.js,NestJS,PostgreSQL}', '{SQL}', 'Fintech', 'technology-hub', '2026-11-12T08:00:00.000Z', 'published', 'mock', '{Design and maintain settlement and reconciliation services,Own a service end to end\, from schema design through on-call,Write the integration tests that keep ledger behaviour honest,Work with partner banks on API contracts}', '{3+ years building production backend services,Comfortable with relational data modelling and transactions,Experience with a typed Node.js codebase,Clear written communication — decisions get written down here}', true, '2026-09-28T08:00:00.000Z'),
  ('job-002', 'org-keystone', 'Keystone Talent', 'Talent Acquisition Partner', 'Run full-cycle hiring for operations and finance clients. You own the brief, the shortlist and the offer conversation.', 480000, 700000, 'NGN', 'month', 'Lagos / Hybrid', 'hybrid', 'full-time', 'mid', '{Recruitment,Stakeholder Management,Excel}', '{Communication}', 'Recruitment', 'recruitment-agency', '2026-11-16T09:30:00.000Z', 'published', 'mock', '{Take hiring briefs and translate them into realistic search strategies,Run structured assessments before client introduction,Manage candidate experience from first call to offer,Report pipeline health to client stakeholders weekly}', '{3+ years in agency or in-house recruitment,Track record of closing mid-to-senior roles,Strong stakeholder management,Comfortable living in a spreadsheet}', true, '2026-10-02T09:30:00.000Z'),
  ('job-003', 'org-atlas-holdings', 'Atlas Holdings', 'HR Operations Lead', 'Lead the HR operations function across four business units — payroll, onboarding, records and the systems that hold them together.', 700000, 1000000, 'NGN', 'month', 'Lagos, Nigeria', 'onsite', 'full-time', 'senior', '{HR Operations,Payroll,Project Management}', '{Excel}', 'Conglomerate', 'corporate-district', '2026-11-09T11:00:00.000Z', 'published', 'mock', '{Own payroll accuracy across 3\,000+ employees,Standardise onboarding across business units,Select and roll out a new HRIS,Line manage a team of five}', '{5+ years in HR operations,Payroll ownership at scale,Experience running a systems migration,People management experience}', false, '2026-09-25T11:00:00.000Z'),
  ('job-004', 'org-signal-labs', 'Signal Labs', 'People Systems Analyst', 'Sit between the people team and engineering: automate the hiring and onboarding workflows that currently run on copy-paste.', 550000, 820000, 'NGN', 'month', 'Remote', 'remote', 'full-time', 'mid', '{HR Operations,AI Automation,Excel}', '{Data Analysis}', 'Technology', 'technology-hub', '2026-11-15T14:20:00.000Z', 'published', 'mock', '{Map and automate people workflows end to end,Build reporting on hiring funnel and retention,Administer the HR and ATS tooling,Write the runbooks the team follows}', '{2+ years in HR operations or people analytics,Strong spreadsheet and data skills,Comfortable building no-code or low-code automations,Able to work independently across time zones}', true, '2026-10-01T14:20:00.000Z'),
  ('job-005', 'org-northwind', 'Northwind Systems', 'Frontend Engineer', 'Build the merchant dashboard that thousands of businesses use to reconcile their settlements every morning.', 450000, 720000, 'NGN', 'month', 'Lagos / Hybrid', 'hybrid', 'full-time', 'mid', '{React,Figma,Communication}', '{}', 'Fintech', 'technology-hub', '2026-11-04T08:00:00.000Z', 'published', 'mock', '{Build and maintain the merchant dashboard,Own accessibility and performance budgets,Partner with design on a shared component library}', '{3+ years with React in production,Strong CSS fundamentals,Experience with data-dense interfaces}', false, '2026-09-20T08:00:00.000Z'),
  ('job-006', 'org-meridian', 'Meridian Capital Partners', 'Financial Analyst', 'Support infrastructure and energy coverage: build models, write the memo, sit in the room while it is argued over.', 400000, 600000, 'NGN', 'month', 'Lagos, Nigeria', 'onsite', 'full-time', 'junior', '{Financial Modelling,Excel,Communication}', '{}', 'Financial Services', 'finance-district', '2026-11-02T10:00:00.000Z', 'published', 'mock', '{Build and maintain valuation models,Draft investment memos and committee materials,Track sector news and company filings}', '{1-3 years in analysis\, audit or consulting,Strong Excel modelling,Clear written English}', false, '2026-09-18T10:00:00.000Z'),
  ('job-007', 'org-harbour-co', 'Harbour & Co.', 'Audit Associate', 'Join the graduate audit intake. Structured training, rotating client portfolios and a clear path to senior associate in three years.', 280000, 420000, 'NGN', 'month', 'Lagos, Nigeria', 'onsite', 'full-time', 'entry', '{Audit,IFRS,Excel}', '{}', 'Accounting', 'finance-district', '2026-10-27T09:00:00.000Z', 'published', 'mock', '{Execute audit fieldwork under senior supervision,Prepare working papers to firm standard,Draft client correspondence}', '{Degree in accounting\, finance or economics,Progress toward ACA / ACCA,Attention to detail}', false, '2026-09-12T09:00:00.000Z'),
  ('job-008', 'org-lumen', 'Lumen Studio', 'Product Designer', 'Work across two or three client products at a time, from early concept through to a shipped interface and a handover kit.', 520000, 850000, 'NGN', 'month', 'Remote (WAT ±3)', 'remote', 'full-time', 'mid', '{Figma,Communication,Motion Design}', '{}', 'Design & Media', 'creative-district', '2026-11-13T13:00:00.000Z', 'published', 'mock', '{Run discovery and concept work with clients,Design end-to-end product flows,Maintain the studio design system}', '{Portfolio showing shipped product work,Fluent in Figma,Comfortable presenting to clients}', false, '2026-09-29T13:00:00.000Z'),
