  ('job-010', 'org-vitalis', 'Vitalis Health Group', 'Clinical Administrator', 'Run the administrative spine of a busy outpatient clinic: scheduling, records, and the handoffs between clinical teams.', 320000, 480000, 'NGN', 'month', 'Abuja, Nigeria', 'onsite', 'full-time', 'mid', '{Clinical Administration,Excel,Communication}', '{}', 'Healthcare', 'healthcare-district', '2026-10-31T07:45:00.000Z', 'published', 'mock', '{Coordinate clinic scheduling across departments,Maintain patient records to compliance standard,Support the clinical leads with reporting}', '{3+ years in healthcare administration,Records and compliance experience,Calm under pressure}', false, '2026-09-16T07:45:00.000Z'),
  ('job-011', 'org-vitalis', 'Vitalis Health Group', 'Healthcare Recruiter', 'Hire nurses, clinicians and allied health staff across eleven sites. High volume, high standards, strong internal support.', 450000, 680000, 'NGN', 'month', 'Abuja / Hybrid', 'hybrid', 'full-time', 'mid', '{Recruitment,HR Operations,Communication}', '{Stakeholder Management}', 'Healthcare', 'healthcare-district', '2026-11-17T08:15:00.000Z', 'published', 'mock', '{Own clinical hiring pipelines across sites,Run credential checks with the compliance team,Build a bench of locum candidates}', '{3+ years recruiting\, ideally clinical,Comfortable with high-volume pipelines,Strong candidate care}', true, '2026-10-03T08:15:00.000Z'),
  ('job-012', 'org-azure-bay', 'Azure Bay Hotels', 'Guest Experience Manager', 'Own the guest journey at a 120-room property, from arrival through to the review that follows.', 380000, 560000, 'NGN', 'month', 'Lagos, Nigeria', 'onsite', 'full-time', 'mid', '{Guest Relations,Communication,Stakeholder Management}', '{}', 'Hospitality', 'hospitality-district', '2026-10-29T12:00:00.000Z', 'published', 'mock', '{Lead the front-of-house team across shifts,Resolve escalated guest issues,Run the service training programme on property}', '{3+ years in hospitality operations,Team leadership experience,Service recovery instincts}', false, '2026-09-14T12:00:00.000Z'),
  ('job-013', 'org-azure-bay', 'Azure Bay Hotels', 'Hospitality Training Coordinator', 'Run the group academy: schedule cohorts, track certification, and keep nine properties on the same service standard.', 300000, 440000, 'NGN', 'month', 'Lagos / Hybrid', 'hybrid', 'full-time', 'junior', '{HR Operations,Communication,Excel}', '{}', 'Hospitality', 'hospitality-district', '2026-11-14T10:10:00.000Z', 'published', 'mock', '{Schedule and run training cohorts,Track certification across properties,Maintain the training content library}', '{2+ years in L&D\, HR or hospitality operations,Strong organisation,Confident presenting}', false, '2026-09-30T10:10:00.000Z'),
  ('job-014', 'org-signal-labs', 'Signal Labs', 'Machine Learning Engineer', 'Own demand forecasting models in production — not notebooks, services that distributors plan their week around.', 900000, 1400000, 'NGN', 'month', 'Remote', 'remote', 'full-time', 'senior', '{Python,Data Analysis,SQL}', '{}', 'Technology', 'technology-hub', '2026-10-23T09:00:00.000Z', 'published', 'mock', '{Take forecasting models from research to production,Own model monitoring and retraining,Partner with product on what is worth modelling}', '{4+ years applied ML in production,Strong Python,Experience with time series}', false, '2026-09-08T09:00:00.000Z'),
  ('job-015', 'org-brightpath', 'Brightpath Learning', 'Learning Experience Designer', 'Design short courses that working professionals can actually finish, and the assessments that make the certificate mean something.', 420000, 650000, 'NGN', 'month', 'Remote', 'remote', 'full-time', 'mid', '{Communication,Project Management,Data Analysis}', '{}', 'Education', 'university-campus', '2026-11-10T15:00:00.000Z', 'published', 'mock', '{Design course structure and assessment,Work with subject experts to shape content,Review completion and outcome data each cohort}', '{3+ years in instructional or learning design,Assessment design experience,Data-informed approach}', false, '2026-09-26T15:00:00.000Z'),
  ('job-016', 'org-atlas-holdings', 'Atlas Holdings', 'Operations Analyst', 'Find out why the numbers move. Sit across logistics and retail, build the reporting, and tell the group what it means.', 450000, 680000, 'NGN', 'month', 'Lagos / Hybrid', 'hybrid', 'full-time', 'mid', '{Excel,Data Analysis,Stakeholder Management}', '{Communication}', 'Conglomerate', 'corporate-district', '2026-11-18T08:30:00.000Z', 'published', 'mock', '{Build and own operational reporting,Investigate variance across business units,Present findings to the group operations director}', '{3+ years in an analytical role,Advanced Excel,Able to present to senior stakeholders}', false, '2026-10-04T08:30:00.000Z'),
  ('job-017', 'org-keystone', 'Keystone Talent', 'Recruitment Coordinator', 'Keep the engine running: scheduling, candidate comms, and the ATS hygiene that makes everyone else faster.', 220000, 320000, 'NGN', 'month', 'Remote', 'remote', 'part-time', 'junior', '{Recruitment,Communication,Excel}', '{}', 'Recruitment', 'recruitment-agency', '2026-11-11T09:45:00.000Z', 'published', 'mock', '{Schedule interviews across time zones,Keep the ATS accurate and current,Send candidate updates on time\, every time}', '{1+ year in a coordination role,Excellent written communication,Calm with a busy calendar}', false, '2026-09-27T09:45:00.000Z'),
  ('job-018', 'org-northwind', 'Northwind Systems', 'Sales Development Representative', 'First commercial conversation with merchants considering Northwind. Research, outreach, qualify, hand over.', 250000, 400000, 'NGN', 'month', 'Lagos, Nigeria', 'onsite', 'full-time', 'entry', '{Sales,Communication}', '{}', 'Fintech', 'corporate-district', '2026-10-26T10:30:00.000Z', 'published', 'mock', '{Research and qualify inbound and outbound leads,Run first discovery calls,Keep the CRM honest}', '{Any sales or customer-facing experience,Resilient and curious,Clear phone manner}', false, '2026-09-11T10:30:00.000Z'),
  ('job-019', 'org-harbour-co', 'Harbour & Co.', 'Payroll Specialist', 'Run payroll for the firm and a portfolio of outsourced clients. Deadlines are real and the numbers have to be right.', 420000, 620000, 'NGN', 'month', 'Lagos / Hybrid', 'hybrid', 'full-time', 'mid', '{Payroll,Excel,HR Operations}', '{}', 'Accounting', 'finance-district', '2026-11-15T07:50:00.000Z', 'published', 'mock', '{Process monthly payroll across multiple entities,Handle statutory filings and reconciliations,Resolve employee payroll queries}', '{3+ years payroll experience,Statutory filing knowledge,Advanced Excel}', false, '2026-10-01T07:50:00.000Z'),
