  ('job-021', 'org-atlas-holdings', 'Atlas Holdings', 'Graduate Trainee — People & Culture', 'Twelve-month rotation across recruitment, learning and HR operations, with a mentor in each rotation.', 180000, 240000, 'NGN', 'month', 'Lagos, Nigeria', 'onsite', 'internship', 'entry', '{HR Operations,Communication}', '{}', 'Conglomerate', 'corporate-district', '2026-10-14T09:00:00.000Z', 'published', 'mock', '{Rotate across three people functions,Support live projects in each rotation,Present a capstone to the people director}', '{Recent graduate,Interest in people and organisational work,Strong written communication}', false, '2026-08-30T09:00:00.000Z'),
  ('job-022', 'org-brightpath', 'Brightpath Learning', 'Course Facilitator — Data Essentials', 'Facilitate evening cohorts for working professionals learning spreadsheets, SQL and reporting fundamentals.', 200000, 350000, 'NGN', 'month', 'Remote', 'remote', 'part-time', 'mid', '{Excel,SQL,Communication}', '{}', 'Education', 'university-campus', '2026-11-08T18:00:00.000Z', 'published', 'mock', '{Run two live sessions a week,Review learner submissions,Feed content gaps back to the design team}', '{Working knowledge of Excel and SQL,Teaching or mentoring experience,Available evenings WAT}', false, '2026-09-24T18:00:00.000Z')
